def is_good_triple(x, y, z):
    """Checks if (x+1)^y / (x^z + 1) is a positive integer."""
    # Since x, y, z are positive integers, the numerator and denominator are positive integers.
    try:
        numerator = (x + 1)**y
        denominator = x**z + 1

        if denominator == 0:
            # This should not happen since x>=1, z>=1.
            return False

        return numerator % denominator == 0
    except OverflowError:
        # Although Python handles large integers, this is a safeguard.
        return False

MAX_VAL = 30
total_good_triples = 0
count_x2_z2 = 0

# Systematically count all good triples for 1 <= x, y, z <= 30
for x in range(1, MAX_VAL + 1):
    for y in range(1, MAX_VAL + 1):
        for z in range(1, MAX_VAL + 1):
            if is_good_triple(x, y, z):
                total_good_triples += 1

                # Specifically track results for x=2 and z=2
                if x == 2 and z == 2:
